import type { Hooks, Plugin } from "@opencode-ai/plugin"
import { readFile, writeFile, mkdir, rm, readdir, stat, rename } from "node:fs/promises"
import * as path from "node:path"
import * as os from "node:os"

const CYRILLIC: Record<string, string> = {
  а: "a",
  б: "b",
  в: "v",
  г: "g",
  д: "d",
  е: "e",
  ё: "yo",
  ж: "zh",
  з: "z",
  и: "i",
  й: "y",
  к: "k",
  л: "l",
  м: "m",
  н: "n",
  о: "o",
  п: "p",
  р: "r",
  с: "s",
  т: "t",
  у: "u",
  ф: "f",
  х: "h",
  ц: "ts",
  ч: "ch",
  ш: "sh",
  щ: "sch",
  ъ: "",
  ы: "y",
  ь: "",
  э: "e",
  ю: "yu",
  я: "ya",
}

export type Config = {
  root: string
  minMessages: number
  maxDescLen: number
  transliterate: boolean
  deleteOnSessionDelete: boolean
}

export type IndexEntry = {
  path: string
  signature: string
}

export type StatLike = { isDirectory(): boolean; isFile(): boolean }

export type FsLike = {
  readFile: (file: string, encoding: "utf8") => Promise<string>
  writeFile: (file: string, content: string) => Promise<void>
  mkdir: (dir: string, options: { recursive: boolean }) => Promise<unknown>
  rm: (target: string, options?: { force?: boolean }) => Promise<void>
  readdir: (dir: string) => Promise<string[]>
  stat: (target: string) => Promise<StatLike>
  rename: (from: string, to: string) => Promise<void>
}

const realFs: FsLike = {
  readFile: (file, encoding) => readFile(file, encoding),
  writeFile: (file, content) => writeFile(file, content),
  mkdir: (dir, options) => mkdir(dir, options),
  rm: (target, options) => rm(target, options),
  readdir: (dir) => readdir(dir),
  stat: (target) => stat(target),
  rename: (from, to) => rename(from, to),
}

export const DEFAULT_CONFIG: Config = {
  root: "ai-sessions",
  minMessages: 1,
  maxDescLen: 80,
  transliterate: true,
  deleteOnSessionDelete: true,
}

export const SWITCH_EVENT_TYPES: readonly string[] = [
  "message.updated",
  "message.part.updated",
  "session.status",
  "session.idle",
  "session.compacted",
  "session.diff",
  "todo.updated",
  "command.executed",
  "permission.updated",
  "tui.session.select",
]

// --- pure helpers (unit-testable) ---

export function transliterate(input: string): string {
  return [...input.toLowerCase()].map((char) => CYRILLIC[char] ?? char).join("")
}

export function slugify(input: string): string {
  return input
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "")
}

export function sessionSlug(
  title: string,
  id: string,
  config: Pick<Config, "transliterate" | "maxDescLen">,
): string {
  let slug = slugify(config.transliterate ? transliterate(title || "") : title || "")
  if (!slug) slug = `session_${String(id).replace(/^ses_/, "").slice(0, 8)}`
  if (slug.length > config.maxDescLen) slug = slug.slice(0, config.maxDescLen)
  return slug
}

export function pad(value: number): string {
  return String(value).padStart(2, "0")
}

export function dateStamp(date: Date): string {
  return [date.getFullYear(), pad(date.getMonth() + 1), pad(date.getDate())].join("-")
}

export function timeStamp(date: Date): string {
  return [pad(date.getHours()), pad(date.getMinutes())].join("-")
}

export function sessionFileName(
  date: Date,
  title: string,
  id: string,
  config: Pick<Config, "transliterate" | "maxDescLen">,
): string {
  return `${timeStamp(date)}_${sessionSlug(title, id, config)}`
}

export function signature(info: any, messages: any[]): string {
  const body = messages
    .map((message) => [message.info.id, (message.parts || []).map((part: any) => part.id).join(",")].join(":"))
    .join("|")
  return JSON.stringify([info.title, info.time?.updated ?? null, messages.length, body])
}

// --- fs-backed helpers (fs injected for unit tests) ---

export async function readJson<T>(fs: FsLike, file: string): Promise<T | undefined> {
  try {
    return JSON.parse(await fs.readFile(file, "utf8")) as T
  } catch {
    return undefined
  }
}

export async function atomicWrite(fs: FsLike, file: string, content: string) {
  await fs.mkdir(path.dirname(file), { recursive: true })
  const tmp = `${file}.${process.pid}.tmp`
  await fs.writeFile(tmp, content)
  try {
    await fs.rename(tmp, file)
  } catch {
    await fs.rm(file, { force: true })
    await fs.rename(tmp, file)
  }
}

export async function pickPath(fs: FsLike, root: string, dir: string, name: string, id: string): Promise<string> {
  for (let attempt = 0; ; attempt++) {
    const suffix = attempt === 0 ? "" : `_${attempt + 1}`
    const rel = path.join(dir, `${name}${suffix}.json`)
    const abs = path.join(root, rel)
    let exists = false
    try {
      await fs.stat(abs)
      exists = true
    } catch {}
    if (!exists) return rel
    const existing = await readJson<{ info?: { id?: string } }>(fs, abs)
    if (existing?.info?.id === id) return rel
  }
}

async function statEntry(fs: FsLike, target: string): Promise<StatLike | undefined> {
  try {
    return await fs.stat(target)
  } catch {
    return undefined
  }
}

export async function listJsonFiles(fs: FsLike, dir: string): Promise<string[]> {
  const out: string[] = []
  let entries: string[] = []
  try {
    entries = await fs.readdir(dir)
  } catch {
    return out
  }
  for (const entry of entries) {
    const full = path.join(dir, entry)
    const entryStat = await statEntry(fs, full)
    if (!entryStat) continue
    if (entryStat.isDirectory()) {
      out.push(...(await listJsonFiles(fs, full)))
    } else if (entryStat.isFile() && entry.endsWith(".json") && entry !== ".index.json") {
      out.push(full)
    }
  }
  return out
}

export function configPaths(baseDir: string, homedir: string): string[] {
  return [
    path.join(homedir, ".config", "opencode", "session-saver.json"),
    path.join(baseDir, ".opencode", "session-saver.json"),
  ]
}

export async function loadConfig(fs: FsLike, paths: string[]): Promise<Config> {
  const merged: Config = { ...DEFAULT_CONFIG }
  for (const file of paths) {
    try {
      Object.assign(merged, JSON.parse(await fs.readFile(file, "utf8")))
    } catch {}
  }
  merged.maxDescLen = Math.max(1, merged.maxDescLen)
  merged.minMessages = Math.max(0, merged.minMessages)
  return merged
}

// --- plugin ---

export type SessionSaverDeps = {
  now?: () => Date
  fs?: FsLike
  homedir?: () => string
}

export function createSessionSaver(deps: SessionSaverDeps = {}): Plugin {
  return async ({ client, directory, worktree }) => {
    const fs = deps.fs ?? realFs
    const now = deps.now ?? (() => new Date())
    const homedir = deps.homedir ?? (() => os.homedir())

    const usableWorktree = worktree && path.resolve(worktree) !== "/"
    const baseDir = usableWorktree ? worktree : directory
    const config = await loadConfig(fs, configPaths(baseDir, homedir()))
    const root = path.isAbsolute(config.root) ? config.root : path.join(baseDir, config.root)

    const sessionMap = new Map<string, IndexEntry>()
    const topLevelCache = new Map<string, boolean>()
    let activeSession: string | undefined
    let tail = Promise.resolve()
    let warm = false

    const indexFile = path.join(root, ".index.json")

    function enqueue<T>(fn: () => Promise<T>): Promise<T> {
      const run = tail.then(fn, fn)
      tail = run.then(
        () => undefined,
        () => undefined,
      )
      return run
    }

    function toAbs(rel: string): string {
      return path.join(root, rel)
    }

    async function isTopLevel(id: string): Promise<boolean> {
      const cached = topLevelCache.get(id)
      if (cached !== undefined) return cached
      let top = true
      try {
        const res = await client.session.get({ path: { id } })
        if (!res.error && res.data?.parentID) top = false
      } catch {}
      topLevelCache.set(id, top)
      return top
    }

    async function saveIndex() {
      const payload = JSON.stringify({ version: 1, sessions: Object.fromEntries(sessionMap) }, null, 2)
      await atomicWrite(fs, indexFile, payload)
    }

    async function rebuildIndex() {
      const found = new Set<string>()
      for (const file of await listJsonFiles(fs, root)) {
        try {
          const data = await readJson<{ info?: any; messages?: any[] }>(fs, file)
          if (!data?.info?.id) continue
          const id = String(data.info.id)
          found.add(id)
          sessionMap.set(id, {
            path: path.relative(root, file),
            signature: signature(data.info, data.messages || []),
          })
        } catch {}
      }
      for (const id of [...sessionMap.keys()]) {
        if (!found.has(id)) sessionMap.delete(id)
      }
      topLevelCache.clear()
      activeSession = undefined
      await saveIndex()
      warm = true
    }

    async function saveSession(id: string) {
      try {
        if (!id || !(await isTopLevel(id))) return
        const sessionRes = await client.session.get({ path: { id } })
        if (sessionRes.error || !sessionRes.data) return
        const info: any = sessionRes.data
        const messagesRes: any = await client.session.messages({ path: { id } })
        const messages: any[] = messagesRes.data || []
        if (messages.length < config.minMessages) return
        const sig = signature(info, messages)
        const previous = sessionMap.get(id)
        if (previous && previous.signature === sig) return
        const date = now()
        const rel = await pickPath(fs, root, dateStamp(date), sessionFileName(date, info.title, id, config), id)
        const abs = toAbs(rel)
        await atomicWrite(fs, abs, JSON.stringify({ info, messages }, null, 2))
        if (previous && previous.path !== rel) {
          await fs.rm(toAbs(previous.path), { force: true })
        }
        sessionMap.set(id, { path: rel, signature: sig })
        await saveIndex()
      } catch (error) {
        console.error("[session-saver] save failed", error)
      }
    }

    async function removeSession(id: string) {
      try {
        if (!config.deleteOnSessionDelete) return
        const previous = sessionMap.get(id)
        if (!previous) return
        await fs.rm(toAbs(previous.path), { force: true })
        sessionMap.delete(id)
        await saveIndex()
      } catch (error) {
        console.error("[session-saver] delete failed", error)
      }
    }

    async function finalizeSwitch(id: string) {
      if (!(await isTopLevel(id))) return
      if (activeSession && activeSession !== id) await saveSession(activeSession)
      activeSession = id
    }

    async function onSessionEvent(id: string) {
      if (!id) return
      if (activeSession && activeSession !== id) {
        await finalizeSwitch(id)
      } else if (!activeSession) {
        if (await isTopLevel(id)) activeSession = id
      }
    }

    const event: Hooks["event"] = async ({ event }) => {
      await enqueue(async () => {
        const current: any = event
        const type: string = current?.type || ""
        const properties: any = current?.properties || {}
        try {
          if (type === "session.created") {
            if (properties?.info?.id && !properties.info.parentID) {
              await finalizeSwitch(String(properties.info.id))
            }
          } else if (type === "session.deleted") {
            const id = properties?.info?.id
            if (id) {
              await removeSession(String(id))
              if (activeSession === id) activeSession = undefined
            }
          } else if (SWITCH_EVENT_TYPES.includes(type)) {
            await onSessionEvent(properties?.sessionID || properties?.sessionId)
          }
        } catch (error) {
          console.error("[session-saver] event failed", type, error)
        }
      })
    }

    const dispose = async () => {
      await Promise.race([
        enqueue(async () => {
          if (!warm) return
          if (activeSession) await saveSession(activeSession)
        }),
        new Promise((resolve) => setTimeout(resolve, 4000)),
      ])
    }

    await enqueue(async () => {
      try {
        await rebuildIndex()
      } catch (error) {
        console.error("[session-saver] init rebuild failed", error)
      }
    })

    return { event, dispose }
  }
}

export default createSessionSaver()

import { test } from "node:test"
import assert from "node:assert/strict"
import { mkdtemp, mkdir, rm, readFile, writeFile, readdir, stat } from "node:fs/promises"
import * as os from "node:os"
import * as path from "node:path"
import {
  DEFAULT_CONFIG,
  atomicWrite,
  configPaths,
  createSessionSaver,
  dateStamp,
  loadConfig,
  pickPath,
  sessionFileName,
  sessionSlug,
  signature,
  slugify,
  timeStamp,
  transliterate,
  type FsLike,
} from "./session-saver.ts"

// --- helpers ---

function memoryFs(files: Record<string, string> = {}): FsLike {
  const data = new Map(Object.entries(files))
  return {
    async readFile(file) {
      const content = data.get(file)
      if (content === undefined) throw new Error("ENOENT")
      return content
    },
    async writeFile(file, content) {
      data.set(file, content)
    },
    async mkdir() {},
    async rm(target) {
      data.delete(target)
    },
    async readdir(dir) {
      const names = new Set<string>()
      for (const key of data.keys()) {
        if (path.dirname(key) === dir) names.add(path.basename(key))
      }
      return [...names]
    },
    async stat(target) {
      if (!data.has(target)) throw new Error("ENOENT")
      return { isDirectory: () => false, isFile: () => true }
    },
    async rename(from, to) {
      const content = data.get(from)
      if (content === undefined) throw new Error("ENOENT")
      data.delete(from)
      data.set(to, content)
    },
  }
}

const msg = (id: string) => ({ info: { id }, parts: [{ id: `p-${id}` }] })

type FakeSession = { info: any; messages: any[] }

function fakeClient(sessions: Map<string, FakeSession>) {
  return {
    session: {
      get: async (args: any) => {
        const entry = sessions.get(args.path.id)
        if (!entry) return { error: true }
        return { data: entry.info }
      },
      messages: async (args: any) => ({ data: sessions.get(args.path.id)?.messages ?? [] }),
    },
  }
}

type Env = { worktree: string; home: string; clock: { value: Date } }

async function makeEnv(projectConfig?: string): Promise<Env> {
  const worktree = await mkdtemp(path.join(os.tmpdir(), "ss-wt-"))
  const home = await mkdtemp(path.join(os.tmpdir(), "ss-home-"))
  if (projectConfig !== undefined) {
    await mkdir(path.join(worktree, ".opencode"), { recursive: true })
    await writeFile(path.join(worktree, ".opencode", "session-saver.json"), projectConfig)
  }
  return { worktree, home, clock: { value: new Date(2026, 8, 16, 15, 8) } }
}

async function cleanup(env: Env) {
  await rm(env.worktree, { recursive: true, force: true })
  await rm(env.home, { recursive: true, force: true })
}

async function startPlugin(env: Env, sessions: Map<string, FakeSession>) {
  const plugin = createSessionSaver({ now: () => env.clock.value, homedir: () => env.home })
  const hooks: any = await plugin({
    client: fakeClient(sessions),
    directory: env.worktree,
    worktree: env.worktree,
  } as any)
  return hooks
}

const created = (id: string, parentID?: string) => ({
  event: { type: "session.created", properties: { info: { id, ...(parentID ? { parentID } : {}) } } },
})
const updated = (sessionID: string) => ({ event: { type: "message.updated", properties: { sessionID } } })
const deleted = (id: string) => ({ event: { type: "session.deleted", properties: { info: { id } } } })

async function sessionFiles(root: string): Promise<string[]> {
  const out: string[] = []
  const walk = async (dir: string) => {
    let entries: string[] = []
    try {
      entries = await readdir(dir)
    } catch {
      return
    }
    for (const entry of entries) {
      const full = path.join(dir, entry)
      const s = await stat(full)
      if (s.isDirectory()) await walk(full)
      else if (entry.endsWith(".json") && entry !== ".index.json") out.push(path.relative(root, full))
    }
  }
  await walk(root)
  return out.sort()
}

async function readJsonAbs(file: string): Promise<any> {
  return JSON.parse(await readFile(file, "utf8"))
}

// --- unit tests ---

test("transliterate maps Cyrillic to Latin", () => {
  assert.equal(transliterate("Привет"), "privet")
  assert.equal(transliterate("Ёжик"), "yozhik")
  assert.equal(transliterate("ABC"), "abc")
})

test("slugify collapses non-alphanumerics", () => {
  assert.equal(slugify("Hello,  World!"), "hello_world")
  assert.equal(slugify("---"), "")
})

test("sessionSlug: transliteration, fallback, truncation", () => {
  assert.equal(sessionSlug("Первая сессия", "ses_x", DEFAULT_CONFIG), "pervaya_sessiya")
  assert.equal(sessionSlug("", "ses_abcdef1234567890", DEFAULT_CONFIG), "session_abcdef12")
  assert.equal(sessionSlug("a".repeat(100), "ses_x", DEFAULT_CONFIG), "a".repeat(80))
  assert.equal(sessionSlug("Разработка", "ses_x", { ...DEFAULT_CONFIG, transliterate: false }), "session_x")
})

test("dateStamp / timeStamp / sessionFileName", () => {
  const date = new Date(2026, 8, 16, 15, 8)
  assert.equal(dateStamp(date), "2026-09-16")
  assert.equal(timeStamp(date), "15-08")
  assert.equal(sessionFileName(date, "Первая сессия", "ses_x", DEFAULT_CONFIG), "15-08_pervaya_sessiya")
})

test("signature is stable and sensitive to every component", () => {
  const info = { title: "t", time: { updated: "u1" } }
  const messages = [msg("m1"), msg("m2")]
  const base = signature(info, messages)
  assert.equal(signature({ title: "t", time: { updated: "u1" } }, [msg("m1"), msg("m2")]), base)
  assert.notEqual(signature({ title: "t2", time: { updated: "u1" } }, messages), base)
  assert.notEqual(signature({ title: "t", time: { updated: "u2" } }, messages), base)
  assert.notEqual(signature(info, [msg("m1")]), base)
  assert.notEqual(signature(info, [msg("mX"), msg("m2")]), base)
  assert.notEqual(signature(info, [{ info: { id: "m1" }, parts: [{ id: "other" }] }, msg("m2")]), base)
  assert.notEqual(signature(info, [{ info: { id: "m1" } }, msg("m2")]), base)
})

test("loadConfig: defaults, precedence (project wins), invalid JSON skipped, clamped", async () => {
  assert.deepEqual(await loadConfig(memoryFs(), []), DEFAULT_CONFIG)

  const fs = memoryFs({
    "/home/u/.config/opencode/session-saver.json": JSON.stringify({ root: "global-root", maxDescLen: 10 }),
    "/proj/.opencode/session-saver.json": JSON.stringify({ root: "proj-root", minMessages: 2 }),
  })
  const cfg = await loadConfig(fs, configPaths("/proj", "/home/u"))
  assert.equal(cfg.root, "proj-root")
  assert.equal(cfg.maxDescLen, 10)
  assert.equal(cfg.minMessages, 2)

  const broken = memoryFs({
    "/home/u/.config/opencode/session-saver.json": "not json",
    "/proj/.opencode/session-saver.json": JSON.stringify({ maxDescLen: 0, minMessages: -3 }),
  })
  const clamped = await loadConfig(broken, configPaths("/proj", "/home/u"))
  assert.equal(clamped.root, DEFAULT_CONFIG.root)
  assert.equal(clamped.maxDescLen, 1)
  assert.equal(clamped.minMessages, 0)

  assert.deepEqual(configPaths("/proj", "/home/u"), [
    "/home/u/.config/opencode/session-saver.json",
    "/proj/.opencode/session-saver.json",
  ])
})

test("pickPath: fresh name, reuse by id, _2/_3 collisions", async () => {
  const root = "/r"
  const fresh = memoryFs()
  assert.equal(await pickPath(fresh, root, "2026-09-16", "15-08_a", "ses_1"), "2026-09-16/15-08_a.json")

  const sameId = memoryFs({ "/r/2026-09-16/15-08_a.json": JSON.stringify({ info: { id: "ses_1" } }) })
  assert.equal(await pickPath(sameId, root, "2026-09-16", "15-08_a", "ses_1"), "2026-09-16/15-08_a.json")

  const oneCollision = memoryFs({ "/r/2026-09-16/15-08_a.json": JSON.stringify({ info: { id: "ses_9" } }) })
  assert.equal(await pickPath(oneCollision, root, "2026-09-16", "15-08_a", "ses_1"), "2026-09-16/15-08_a_2.json")

  const twoCollisions = memoryFs({
    "/r/2026-09-16/15-08_a.json": JSON.stringify({ info: { id: "ses_9" } }),
    "/r/2026-09-16/15-08_a_2.json": JSON.stringify({ info: { id: "ses_8" } }),
  })
  assert.equal(await pickPath(twoCollisions, root, "2026-09-16", "15-08_a", "ses_1"), "2026-09-16/15-08_a_3.json")
})

test("atomicWrite: rename, and rm+rename fallback when rename fails", async () => {
  const ok = memoryFs({ "/r/f.json": "old" })
  await atomicWrite(ok, "/r/f.json", "new")
  assert.equal(await ok.readFile("/r/f.json", "utf8"), "new")
  assert.ok(!(await ok.readdir("/r")).includes("f.json.123.tmp"))

  const base = memoryFs({ "/r/f.json": "old" })
  let failFirst = true
  const flaky2: FsLike = {
    readFile: (file, enc) => base.readFile(file, enc),
    writeFile: (file, content) => base.writeFile(file, content),
    mkdir: (dir, opts) => base.mkdir(dir, opts),
    rm: (target, opts) => base.rm(target, opts),
    readdir: (dir) => base.readdir(dir),
    stat: (target) => base.stat(target),
    rename: async (from, to) => {
      if (failFirst) {
        failFirst = false
        throw new Error("EEXIST")
      }
      return base.rename(from, to)
    },
  }
  await atomicWrite(flaky2, "/r/f.json", "new2")
  assert.equal(await base.readFile("/r/f.json", "utf8"), "new2")
})

// --- integration tests ---

test("saves only on switch and dispose, with path scheme and index", async () => {
  const env = await makeEnv()
  try {
    const sessions = new Map<string, FakeSession>([
      ["ses_aaa", { info: { id: "ses_aaa", title: "Первая сессия" }, messages: [msg("m1")] }],
      ["ses_bbb", { info: { id: "ses_bbb", title: "Second" }, messages: [msg("m1")] }],
    ])
    const hooks = await startPlugin(env, sessions)

    await hooks.event(created("ses_aaa"))
    assert.deepEqual(await sessionFiles(path.join(env.worktree, "ai-sessions")), [])
    const emptyIndex = await readJsonAbs(path.join(env.worktree, "ai-sessions", ".index.json"))
    assert.deepEqual(emptyIndex, { version: 1, sessions: {} })

    await hooks.event(updated("ses_aaa"))
    assert.deepEqual(await sessionFiles(path.join(env.worktree, "ai-sessions")), [])

    await hooks.event(created("ses_bbb"))
    assert.deepEqual(await sessionFiles(path.join(env.worktree, "ai-sessions")), [
      "2026-09-16/15-08_pervaya_sessiya.json",
    ])
    const savedA = await readJsonAbs(path.join(env.worktree, "ai-sessions", "2026-09-16", "15-08_pervaya_sessiya.json"))
    assert.equal(savedA.info.id, "ses_aaa")
    assert.equal(savedA.messages.length, 1)

    await hooks.dispose()
    assert.deepEqual(await sessionFiles(path.join(env.worktree, "ai-sessions")), [
      "2026-09-16/15-08_pervaya_sessiya.json",
